import React, { forwardRef, useEffect, useImperativeHandle, useRef } from "react";

const formatTime = (value) => {
  const total = Math.max(0, Number(value) || 0);
  const minutes = Math.floor(total / 60);
  const seconds = Math.floor(total % 60);
  const tenths = Math.floor((total - Math.floor(total)) * 10);
  return `${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}.${tenths}`;
};

const VideoPlayer = forwardRef(
  (
    {
      src,
      isPlaying,
      currentTime,
      onTogglePlay,
      onDurationChange,
      onTimeUpdate,
      onPlay,
      onPause,
      hasVideo,
      tamperedRanges = [], // ✅ NEW PROP
    },
    ref
  ) => {
    const localRef = useRef(null);

    useImperativeHandle(ref, () => localRef.current, [localRef]);

    useEffect(() => {
      const video = localRef.current;
      if (!video) return;

      const handleLoadedMetadata = () => onDurationChange?.(video.duration || 0);
      const handleTimeUpdateInternal = () => onTimeUpdate?.(video.currentTime || 0);
      const handlePlay = () => onPlay?.();
      const handlePause = () => onPause?.();

      video.addEventListener("loadedmetadata", handleLoadedMetadata);
      video.addEventListener("timeupdate", handleTimeUpdateInternal);
      video.addEventListener("play", handlePlay);
      video.addEventListener("pause", handlePause);

      return () => {
        video.removeEventListener("loadedmetadata", handleLoadedMetadata);
        video.removeEventListener("timeupdate", handleTimeUpdateInternal);
        video.removeEventListener("play", handlePlay);
        video.removeEventListener("pause", handlePause);
      };
    }, [onDurationChange, onTimeUpdate, onPlay, onPause, src]);

    // ✅ Detect tampered moment
    const isTamperedFrame = tamperedRanges.some(
      (range) => currentTime >= range.start_s && currentTime <= range.end_s
    );

    return (
      <div className="relative h-full w-full overflow-hidden rounded-[28px] bg-slate-950 shadow-soft">
        <div className="relative h-full w-full bg-slate-900">

          {/* 🎬 VIDEO */}
          <video
            ref={localRef}
            src={src}
            playsInline
            preload="metadata"
            className="h-full w-full object-cover"
            controls={false}
          />

          {/* 🔴 TAMPER OVERLAY */}
          {isTamperedFrame && (
            <div className="tamper-overlay">
              🚨 TAMPERED FRAME
            </div>
          )}

          {/* NO VIDEO PLACEHOLDER */}
          {!hasVideo && (
            <div className="absolute inset-0 flex flex-col items-center justify-center gap-3 bg-slate-950/85 px-6 text-center">
              <div className="inline-flex h-16 w-16 items-center justify-center rounded-full bg-white/10 text-pink-300 shadow-[0_18px_40px_rgba(255,77,109,0.22)]">
                <span className="text-3xl">+</span>
              </div>
              <div>
                <p className="text-sm font-semibold text-white">Drop in your video.</p>
                <p className="mt-2 text-sm text-slate-400">
                  Use the timeline button below to upload a clip and begin editing.
                </p>
              </div>
            </div>
          )}

          {/* EFFECTS */}
          <div className="pointer-events-none absolute inset-0 bg-[radial-gradient(circle_at_center,_rgba(255,255,255,0.08),_transparent_55%)]" />
          <div className="pointer-events-none absolute inset-x-0 bottom-0 h-28 bg-gradient-to-t from-slate-950/95 to-transparent" />

          {/* PLAY BUTTON */}
          <button
            type="button"
            onClick={onTogglePlay}
            className="absolute inset-x-0 bottom-8 mx-auto flex h-16 w-16 items-center justify-center rounded-full bg-white/10 text-white transition duration-200 hover:bg-white/15 focus:outline-none"
            aria-label={isPlaying ? "Pause video" : "Play video"}
          >
            <div className="flex h-12 w-12 items-center justify-center rounded-full bg-slate-950/70 transition duration-200 hover:scale-105">
              <svg viewBox="0 0 24 24" className="h-7 w-7 fill-current">
                {isPlaying ? (
                  <g>
                    <rect x="6" y="5" width="4" height="14" rx="1.5" />
                    <rect x="14" y="5" width="4" height="14" rx="1.5" />
                  </g>
                ) : (
                  <path d="M8 5L19 12L8 19V5Z" />
                )}
              </svg>
            </div>
          </button>

          {/* TIME DISPLAY */}
          <div className="absolute right-4 top-4 rounded-full bg-slate-950/70 px-3 py-2 text-xs font-semibold uppercase tracking-[0.24em] text-slate-200 shadow-lg shadow-black/20">
            {formatTime(currentTime)}
          </div>
        </div>
      </div>
    );
  }
);

export default VideoPlayer;
